SELECT CASE WHEN YEAR(hire_date) < 2024 THEN 'before_2024' WHEN YEAR(hire_date) = 2024 THEN '2024' ELSE 'after_2024' END AS hire_cohort, COUNT(CASE WHEN level = 'L2' THEN 1 END) AS l2_count, COUNT(*) AS num_employees, MIN(salary) AS min_salary FROM employees WHERE hire_date BETWEEN '2024-02-09' AND '2024-05-01' AND manager_id = 40 GROUP BY CASE WHEN YEAR(hire_date) < 2024 THEN 'before_2024' WHEN YEAR(hire_date) = 2024 THEN '2024' ELSE 'after_2024' END HAVING l2_count < 2 ORDER BY 1
